import test from "node:test";
import assert from "node:assert/strict";
import {apply, planner} from "./replay.mjs";

const catalog = {default: 5, studios: new Map([["orchid", 8], ["iris", 2]])};
const request = {service:"studio", action:"book", id:"first", tenant:"orchid", day:"2025-04-02", units:7};

test("Studio allocations preserve replay, conflicts, cancellation and tenant/day accounting", () => {
  const dispatch = planner(catalog);
  assert.deepEqual(dispatch(request), {status:"booked", id:"first", remaining:1});
  assert.equal(dispatch(request).status, "replay");
  assert.equal(dispatch({...request, units:8}).status, "conflict");
  assert.deepEqual(dispatch({...request, id:"extra", units:2}), {status:"full", id:"extra", remaining:1});
  assert.equal(dispatch({...request, id:"tomorrow", day:"2025-04-03"}).status, "booked");
  assert.equal(dispatch({...request, id:"other", tenant:"unlisted", units:5}).status, "booked");
  assert.equal(dispatch({...request, id:"small", tenant:"iris", units:3}).status, "full");
  assert.equal(dispatch({...request, action:"cancel"}).status, "cancelled");
  assert.equal(dispatch(request).status, "cancelled");
  assert.equal(dispatch({...request, id:"replacement", units:8}).status, "booked");
  assert.deepEqual(dispatch({...request, action:"usage"}), {units:8});
});

test("renewals use inherited tenants, overrides, target-day usage and normal replay rules", () => {
  const dispatch = planner(catalog);
  dispatch({...request, action:"import"});
  const renewal = {service:"studio", action:"renew", previous:"first", id:"renewal", day:"2025-05-02"};
  assert.deepEqual(dispatch(renewal), {status:"booked", id:"renewal", remaining:1});
  assert.equal(dispatch(renewal).status, "replay");
  assert.equal(dispatch({...renewal, units:8}).status, "conflict");
  assert.deepEqual(dispatch({...renewal, id:"overflow", units:2}), {status:"full", id:"overflow", remaining:1});
  assert.equal(dispatch({...renewal, id:"last-unit", units:1}).status, "booked");
  dispatch({service:"studio", action:"cancel", id:"renewal"});
  assert.equal(dispatch(renewal).status, "cancelled");
  dispatch({service:"studio", action:"cancel", id:"first"});
  assert.deepEqual(dispatch({...renewal, id:"missing"}), {status:"missing", id:"first"});
});

test("unlisted Studio renewals and all Archive admission retain the default", () => {
  for (const [service, tenant] of [["studio", "unlisted"], ["studio", "iris"], ["archive", "orchid"]]) {
    const dispatch = planner(catalog);
    const cap = tenant === "iris" ? 2 : 5;
    assert.equal(dispatch({...request, service, tenant, units:cap + 1}).status, "full");
    dispatch({...request, service, tenant, units:cap, action:"import"});
    const renewal = {service, action:"renew", previous:"first", id:"next", day:"2025-05-02"};
    assert.equal(dispatch({...renewal, units:cap + 1}).status, "full");
    assert.equal(dispatch(renewal).status, "booked");
  }
});

test("imports remain unbounded, full remaining is clamped, and invalid input stays invalid", () => {
  const dispatch = planner(catalog);
  dispatch({...request, action:"import", units:10});
  assert.deepEqual(dispatch({...request, id:"blocked", units:1}), {status:"full", id:"blocked", remaining:0});
  assert.deepEqual(apply(dispatch, {...request, id:"bad", units:0}), {status:"invalid", field:"units"});
});
