import {execFileSync} from "node:child_process";
import {publicationCalendar, projectCalendar} from "./utilization.mjs";
import {readCatalog} from "./common/limits.mjs";

const catalog = readCatalog();
const pilot = JSON.parse(readFileSync(new URL("./fixtures/pilot.json", import.meta.url)));
const run = (script, args, cwd) => execFileSync(process.execPath,
  [fileURLToPath(new URL(script, import.meta.url)), ...args], {cwd, encoding:"utf8"});

test("publication selects only the inclusive ticket window after the full replay", () => {
  const source = structuredClone(pilot);
  source.operations = [
    {service:"studio", action:"import", id:"old", tenant:"orchid", day:"2025-03-01", units:7},
    {service:"studio", action:"renew", previous:"old", id:"april", day:"2025-04-02"},
    {service:"studio", action:"book", id:"gone", tenant:"orchid", day:"2025-04-03", units:3},
    {service:"studio", action:"cancel", id:"gone"}
  ];
  assert.equal(projectCalendar(source, catalog).length, 12);
  assert.deepEqual(publicationCalendar(source, catalog), [
    {service:"studio", tenant:"orchid", day:"2025-04-02", edition:"orchid-quota", cap:8, used:7, available:1},
    {service:"studio", tenant:"orchid", day:"2025-04-03", edition:"orchid-quota", cap:8, used:0, available:8}
  ]);
  source.window.from = source.window.through;
  assert.equal(publicationCalendar(source, catalog).length, 1);
  source.window.from = "2025-04-04";
  assert.throws(() => publicationCalendar(source, catalog), /reversed/);
});

test("publish-calendar upserts selected cells, preserves other rows, and is byte-idempotent", () => {
  const dir = mkdtempSync(join(tmpdir(), "studio-diary-"));
  try {
    const feed = join(dir, "feed.json"), diary = join(dir, "diary.json");
    const untouched = [
      {service:"archive", tenant:"orchid", day:"2025-04-02", edition:"signed", cap:5, used:1, available:4},
      {service:"studio", tenant:"iris", day:"2025-04-02", edition:"signed", cap:5, used:4, available:1},
      {service:"studio", tenant:"orchid", day:"2025-04-01", edition:"signed", cap:5, used:2, available:3},
      {service:"studio", tenant:"orchid", day:"2025-04-04", edition:"signed", cap:5, used:1, available:4}
    ];
    writeFileSync(feed, JSON.stringify(pilot));
    writeFileSync(diary, JSON.stringify([...untouched,
      {service:"studio", tenant:"orchid", day:"2025-04-02", edition:"old", cap:5, used:0, available:5}]));
    assert.deepEqual(JSON.parse(run("./utilization.mjs", ["publish-calendar", feed, diary])), {edition:"orchid-quota", rows:2});
    const once = readFileSync(diary, "utf8");
    assert.deepEqual(JSON.parse(once), [...untouched, ...publicationCalendar(pilot, catalog)]);
    run("./utilization.mjs", ["publish-calendar", feed, diary]);
    assert.equal(readFileSync(diary, "utf8"), once);
    writeFileSync(feed, JSON.stringify({...pilot, window:{...pilot.window, through:"2025-02-30"}}));
    assert.throws(() => run("./utilization.mjs", ["publish-calendar", feed, diary]));
    assert.equal(readFileSync(diary, "utf8"), once);
  } finally { rmSync(dir, {recursive:true, force:true}); }
});

test("desk-scoped staging queues the current Studio allocation once without Archive changes", () => {
  const dir = mkdtempSync(join(tmpdir(), "studio-release-"));
  try {
    mkdirSync(join(dir, "fixtures"));
    const queue = join(dir, "fixtures/release-queue.json");
    const archive = {release:"summer", service:"archive", default:5, allocations:{}};
    writeFileSync(queue, JSON.stringify([archive]));
    run("./replay.mjs", ["stage", "orchid-quota", "studio"], dir);
    assert.deepEqual(JSON.parse(readFileSync(queue)), [archive,
      {release:"orchid-quota", service:"studio", default:5, allocations:{orchid:8}}]);
    const once = readFileSync(queue, "utf8");
    run("./replay.mjs", ["stage", "orchid-quota", "studio"], dir);
    assert.equal(readFileSync(queue, "utf8"), once);
  } finally { rmSync(dir, {recursive:true, force:true}); }
});
